import "package:flutter_test/flutter_test.dart"; import "../lib/models/user.dart"; void main() { group("User Model Tests", () { test("should create user from json", () { final json = {"_id": "123", "name": "John Doe", "email": "john@example.com", "role": "buyer", "createdAt": "2023-01-01T00:00:00.000Z", "updatedAt": "2023-01-01T00:00:00.000Z"}; final user = User.fromJson(json); expect(user.id, "123"); expect(user.name, "John Doe"); expect(user.email, "john@example.com"); expect(user.role, "buyer"); }); test("should convert user to json", () { final user = User(id: "123", name: "John Doe", email: "john@example.com", role: "buyer", createdAt: DateTime(2023, 1, 1), updatedAt: DateTime(2023, 1, 1)); final json = user.toJson(); expect(json["id"], "123"); expect(json["name"], "John Doe"); expect(json["email"], "john@example.com"); expect(json["role"], "buyer"); }); }); }
